DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.capture_sheet_requirements()'::regprocedure) INTO d; d=replace(d,'IF cardinality(items)=0 THEN SELECT * INTO a FROM public.maintenance_agreements','IF cardinality(items)=0 AND selected IS NULL THEN SELECT x.snapshot INTO selected FROM public.document_attachments x WHERE x.company_id=NEW.company_id AND x.client_id=NEW.client_id AND (x.asset_id=NEW.asset_id OR x.asset_id IS NULL AND x.site_id=NEW.site_id) AND x.snapshot->>''kind''=''checklist'' ORDER BY x.asset_id NULLS LAST,x.created_at DESC LIMIT 1; SELECT coalesce(array_agg(v),''{}'') INTO items FROM jsonb_array_elements_text(coalesce(selected->''items'',''[]'')) WITH ORDINALITY t(v,n) WHERE coalesce(selected->''field_specs''->(n::integer-1)->>''audience'',''both'')<>''client''; END IF; IF cardinality(items)=0 THEN SELECT * INTO a FROM public.maintenance_agreements'); EXECUTE d; END $$;